// Canister landing-page manifest builder.
//
// Loads data/recipes.json (generated by `can-docgen`), renders a per-sandbox
// recipe picker, and emits a canister.toml live preview.
//
// No framework, no build step. Plain DOM mutation.

const state = {
  recipes: [],
  byCategory: new Map(),
  sandboxes: [],
  nextId: 1,
};

const els = {
  status: document.getElementById('builder-status'),
  sandboxes: document.getElementById('sandboxes'),
  addSandbox: document.getElementById('add-sandbox'),
  output: document.querySelector('#output code'),
  outputCli: document.querySelector('#output-cli code'),
  copy: document.getElementById('copy-output'),
  copyCli: document.getElementById('copy-cli'),
  tpl: document.getElementById('sandbox-template'),
};

const CATEGORY_LABELS = {
  core: 'Core',
  languages: 'Languages',
  'package-managers': 'Package managers',
  vcs: 'Version control',
  container: 'Containers & K8s',
  editors: 'Editors',
  system: 'System',
  services: 'Service contracts',
};
const CATEGORY_ORDER = [
  'languages', 'package-managers', 'vcs', 'container', 'editors', 'system', 'services', 'core',
];

async function init() {
  try {
    const resp = await fetch('data/recipes.json', { cache: 'no-cache' });
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    state.recipes = await resp.json();
  } catch (err) {
    showStatus(`Could not load data/recipes.json: ${err.message}. Run \`cargo run -p can-docgen\` to regenerate it.`);
    return;
  }
  state.byCategory = groupByCategory(state.recipes);

  // Seed with a sensible default sandbox.
  addSandbox({ name: 'dev', command: 'bash', egress: '', picks: new Set() });
  render();
}

function groupByCategory(recipes) {
  const m = new Map();
  for (const r of recipes) {
    if (!m.has(r.category)) m.set(r.category, []);
    m.get(r.category).push(r);
  }
  for (const arr of m.values()) arr.sort((a, b) => a.name.localeCompare(b.name));
  return m;
}

function showStatus(message) {
  els.status.textContent = message;
  els.status.hidden = false;
}

function addSandbox(initial) {
  const id = state.nextId++;
  state.sandboxes.push({
    id,
    name: initial?.name ?? `sandbox-${id}`,
    command: initial?.command ?? 'bash',
    egress: initial?.egress ?? '',
    picks: initial?.picks ?? new Set(),
    search: '',
  });
}

function render() {
  // Render each sandbox card.
  els.sandboxes.innerHTML = '';
  for (const sb of state.sandboxes) {
    els.sandboxes.appendChild(buildSandboxCard(sb));
  }
  renderOutput();
}

function buildSandboxCard(sb) {
  const frag = els.tpl.content.cloneNode(true);
  const card = frag.querySelector('[data-sandbox-card]');
  card.dataset.id = sb.id;

  const nameInput = card.querySelector('[data-field="name"]');
  const commandInput = card.querySelector('[data-field="command"]');
  const egressSelect = card.querySelector('[data-field="egress"]');
  const searchInput = card.querySelector('[data-recipe-search]');
  const list = card.querySelector('[data-recipe-list]');
  const summary = card.querySelector('[data-picker-summary]');
  const removeBtn = card.querySelector('[data-remove-sandbox]');
  const nameEcho = card.querySelector('[data-name-echo]');

  nameInput.value = sb.name;
  commandInput.value = sb.command;
  egressSelect.value = sb.egress;
  searchInput.value = sb.search;
  if (nameEcho) nameEcho.textContent = sb.name || 'unnamed';

  nameInput.addEventListener('input', () => {
    sb.name = nameInput.value;
    if (nameEcho) nameEcho.textContent = sb.name || 'unnamed';
    renderOutput();
  });
  commandInput.addEventListener('input', () => { sb.command = commandInput.value; renderOutput(); });
  egressSelect.addEventListener('change', () => { sb.egress = egressSelect.value; renderOutput(); });
  searchInput.addEventListener('input', () => {
    sb.search = searchInput.value;
    applySearchFilter(list, summary, sb);
  });

  removeBtn.addEventListener('click', () => {
    if (state.sandboxes.length === 1) {
      showStatus('A manifest must contain at least one sandbox — keeping this one.');
      return;
    }
    state.sandboxes = state.sandboxes.filter(x => x.id !== sb.id);
    render();
  });

  for (const category of orderedCategories()) {
    const recipes = state.byCategory.get(category) || [];
    if (!recipes.length) continue;
    list.appendChild(buildCategorySection(category, recipes, sb));
  }

  applySearchFilter(list, summary, sb);
  return frag;
}

function orderedCategories() {
  const known = new Set(CATEGORY_ORDER);
  const extras = [...state.byCategory.keys()].filter(c => !known.has(c)).sort();
  return [...CATEGORY_ORDER.filter(c => state.byCategory.has(c)), ...extras];
}

function buildCategorySection(category, recipes, sb) {
  const wrap = document.createElement('section');
  wrap.className = 'category';
  wrap.dataset.category = category;

  const label = document.createElement('h4');
  label.className = 'category-name';
  label.textContent = CATEGORY_LABELS[category] || category;
  label.appendChild(Object.assign(document.createElement('span'), {
    className: 'category-count',
    textContent: ` ${recipes.length}`,
  }));
  wrap.appendChild(label);

  const rows = document.createElement('div');
  rows.className = 'recipe-rows';
  for (const recipe of recipes) {
    rows.appendChild(buildRecipeRow(recipe, sb));
  }
  wrap.appendChild(rows);
  return wrap;
}

function buildRecipeRow(recipe, sb) {
  const row = document.createElement('article');
  row.className = 'recipe-row';
  row.dataset.name = recipe.name;
  const selected = sb.picks.has(recipe.name);
  if (selected) row.classList.add('selected');

  // ---- Header (always visible): toggle button + description ----
  const header = document.createElement('div');
  header.className = 'recipe-row-header';

  const toggle = document.createElement('button');
  toggle.type = 'button';
  toggle.className = 'recipe-toggle';
  toggle.setAttribute('aria-pressed', selected ? 'true' : 'false');
  toggle.setAttribute('aria-label', `Toggle ${recipe.name}`);

  const indicator = document.createElement('span');
  indicator.className = 'recipe-indicator';
  indicator.setAttribute('aria-hidden', 'true');
  toggle.appendChild(indicator);

  const nameWrap = document.createElement('span');
  nameWrap.className = 'recipe-name-wrap';
  const nameEl = document.createElement('span');
  nameEl.className = 'recipe-name';
  nameEl.textContent = recipe.name;
  nameWrap.appendChild(nameEl);

  const auto = (recipe.match_prefix && recipe.match_prefix.length > 0);
  if (auto) {
    const badge = document.createElement('span');
    badge.className = 'badge-auto';
    badge.setAttribute('tabindex', '0');
    badge.dataset.tooltip = `Auto-detected: canister composes this recipe automatically when the resolved binary path starts with one of its match_prefix entries (${recipe.match_prefix.join(', ')}). You don't need to list it explicitly under recipes = [...].`;
    badge.textContent = 'auto';
    nameWrap.appendChild(badge);
  }
  toggle.appendChild(nameWrap);

  toggle.addEventListener('click', (e) => {
    e.stopPropagation();
    const pressed = toggle.getAttribute('aria-pressed') !== 'true';
    toggle.setAttribute('aria-pressed', pressed ? 'true' : 'false');
    row.classList.toggle('selected', pressed);
    if (pressed) sb.picks.add(recipe.name); else sb.picks.delete(recipe.name);
    renderOutput();
  });

  header.appendChild(toggle);

  const desc = document.createElement('p');
  desc.className = 'recipe-desc';
  desc.textContent = recipe.description || 'No description.';
  header.appendChild(desc);

  // ---- Expand chevron: opens the inline detail panel ----
  const expandBtn = document.createElement('button');
  expandBtn.type = 'button';
  expandBtn.className = 'recipe-expand';
  expandBtn.setAttribute('aria-expanded', 'false');
  expandBtn.setAttribute('aria-label', `Show details for ${recipe.name}`);
  expandBtn.innerHTML = '<span class="chevron" aria-hidden="true">▾</span>';
  header.appendChild(expandBtn);

  row.appendChild(header);

  // ---- Detail panel (lazy-rendered on first expand) ----
  const detail = document.createElement('div');
  detail.className = 'recipe-detail';
  detail.hidden = true;
  row.appendChild(detail);

  let detailRendered = false;
  expandBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    const isOpen = expandBtn.getAttribute('aria-expanded') === 'true';
    const next = !isOpen;
    expandBtn.setAttribute('aria-expanded', next ? 'true' : 'false');
    row.classList.toggle('expanded', next);
    detail.hidden = !next;
    if (next && !detailRendered) {
      renderRecipeDetail(detail, recipe);
      detailRendered = true;
    }
  });

  return row;
}

function renderRecipeDetail(host, recipe) {
  host.innerHTML = '';
  const s = recipe.summary || {};
  const contracts = s.host_contracts || [];

  // -- Network contracts (DLP-rich) --
  if (contracts.length > 0) {
    const block = makeBlock('Network contracts', 'network');
    const subtitle = document.createElement('p');
    subtitle.className = 'block-hint';
    subtitle.textContent = 'Each host is gated by an explicit contract — methods, content types, body cap, and DLP credential scope. Anything else is refused before the body is even decoded.';
    block.appendChild(subtitle);

    for (const c of contracts) {
      const item = document.createElement('div');
      item.className = 'host-card';

      const head = document.createElement('div');
      head.className = 'host-card-head';
      const dom = document.createElement('span');
      dom.className = 'host-domain';
      dom.textContent = c.domain;
      head.appendChild(dom);
      if (c.contract_mode) {
        const mode = document.createElement('span');
        mode.className = `host-pill mode-${c.contract_mode}`;
        mode.setAttribute('tabindex', '0');
        mode.dataset.tooltip = c.contract_mode === 'strict'
          ? 'Strict contract: requests to this host MUST satisfy the method / content-type / path / size constraints below. Anything else is refused (415 / 405 / 413) before the body is ever decoded by the DLP scanner.'
          : 'Relaxed contract: connect permission is granted but the shape gate is skipped. Used for upstreams where the content set is too heterogeneous to enumerate — CDN tarballs, raw file servers, blob downloads. DLP still scans bodies.';
        mode.textContent = c.contract_mode;
        head.appendChild(mode);
      }
      item.appendChild(head);

      const stats = document.createElement('dl');
      stats.className = 'host-stats';
      if (c.methods && c.methods.length) addInline(stats, 'methods', c.methods.join(' '));
      else addInline(stats, 'methods', 'any (no shape gate)');
      if (c.content_types && c.content_types.length) addInline(stats, 'content-types', c.content_types.join(', '));
      if (c.paths && c.paths.length) addInline(stats, 'paths', c.paths.join(', '));
      if (typeof c.max_request_bytes === 'number') addInline(stats, 'max body', humanBytes(c.max_request_bytes));
      if (c.allow_credentials && c.allow_credentials.length) {
        addInline(
          stats,
          'DLP scope',
          `allows ${c.allow_credentials.join(', ')} (Block → Warn here)`,
          'DLP detectors named here have their finding downgraded from Block to Warn on this host only. Used to legitimise a credential that belongs on this upstream (e.g. a GitHub PAT in Authorization: Bearer on api.github.com) while still blocking it from leaking elsewhere.'
        );
      }
      item.appendChild(stats);
      block.appendChild(item);
    }
    host.appendChild(block);
  }

  // -- Filesystem --
  const fsAllow = s.filesystem_allow || [];
  const fsWrite = s.filesystem_allow_write || [];
  const fsDeny = s.filesystem_deny || [];
  if (fsAllow.length || fsWrite.length || fsDeny.length) {
    const block = makeBlock('Filesystem', 'fs');
    if (fsAllow.length) appendPathList(block, 'read-only mount', fsAllow);
    if (fsWrite.length) appendPathList(block, 'writable mount', fsWrite);
    if (fsDeny.length) appendPathList(block, 'denied', fsDeny);
    host.appendChild(block);
  }

  // -- Environment --
  if (s.env_passthrough && s.env_passthrough.length) {
    const block = makeBlock('Environment passthrough', 'env');
    const chips = document.createElement('div');
    chips.className = 'env-chips';
    for (const v of s.env_passthrough) {
      const ch = document.createElement('code');
      ch.className = 'env-chip';
      ch.textContent = v;
      chips.appendChild(ch);
    }
    block.appendChild(chips);
    host.appendChild(block);
  }

  // -- Other policy bits --
  const extras = [];
  if (recipe.match_prefix && recipe.match_prefix.length) {
    extras.push(['match_prefix', recipe.match_prefix.join(', '), 'Auto-detected when the resolved binary path starts with one of these.']);
  }
  if (s.egress) extras.push(['egress', s.egress, 'Recipe-level egress stance (overrides sandbox default).']);
  if (s.strict === true) extras.push(['strict', 'true', 'Aborts the sandbox if any isolation layer fails to set up.']);
  if (typeof s.max_pids === 'number') extras.push(['max_pids', String(s.max_pids), 'Cgroup pids.max limit for this sandbox.']);
  if (s.syscalls_allow_extra && s.syscalls_allow_extra.length) extras.push(['syscalls.allow_extra', s.syscalls_allow_extra.join(', '), 'Added to the seccomp allow list on top of the default baseline.']);
  if (s.syscalls_deny_extra && s.syscalls_deny_extra.length) extras.push(['syscalls.deny_extra', s.syscalls_deny_extra.join(', '), 'Removed from the allow list and added to deny.']);

  if (extras.length) {
    const block = makeBlock('Policy', 'policy');
    const dl = document.createElement('dl');
    dl.className = 'policy-dl';
    for (const [k, v, hint] of extras) {
      const dt = document.createElement('dt');
      dt.textContent = k;
      const dd = document.createElement('dd');
      const val = document.createElement('code');
      val.textContent = v;
      dd.appendChild(val);
      if (hint) {
        const h = document.createElement('span');
        h.className = 'policy-hint';
        h.textContent = hint;
        dd.appendChild(h);
      }
      dl.append(dt, dd);
    }
    block.appendChild(dl);
    host.appendChild(block);
  }

  if (host.children.length === 0) {
    const empty = document.createElement('p');
    empty.className = 'detail-empty';
    empty.textContent = 'This recipe declares no filesystem, network, or policy overrides — it inherits base.toml / default.toml only.';
    host.appendChild(empty);
  }
}

function makeBlock(title, kind) {
  const block = document.createElement('section');
  block.className = `detail-block detail-block-${kind}`;
  const h = document.createElement('h5');
  h.className = 'block-title';
  h.textContent = title;
  block.appendChild(h);
  return block;
}

function addInline(dl, label, value, tooltip) {
  const dt = document.createElement('dt');
  dt.textContent = label;
  if (tooltip) {
    dt.dataset.tooltip = tooltip;
    dt.setAttribute('tabindex', '0');
    dt.classList.add('has-tooltip');
  }
  const dd = document.createElement('dd');
  dd.textContent = value;
  dl.append(dt, dd);
}

function appendPathList(host, label, items) {
  const sec = document.createElement('div');
  sec.className = 'path-section';
  const head = document.createElement('div');
  head.className = 'path-section-head';
  head.textContent = `${label} (${items.length})`;
  sec.appendChild(head);
  const ul = document.createElement('ul');
  ul.className = 'path-list';
  for (const item of items) {
    const li = document.createElement('li');
    li.textContent = item;
    ul.appendChild(li);
  }
  sec.appendChild(ul);
  host.appendChild(sec);
}

function humanBytes(n) {
  if (n < 1024) return `${n} B`;
  const units = ['KiB', 'MiB', 'GiB', 'TiB'];
  let i = -1;
  let v = n;
  while (v >= 1024 && i < units.length - 1) { v /= 1024; i++; }
  return `${v.toFixed(v < 10 ? 1 : 0)} ${units[i]}`;
}

function applySearchFilter(listEl, summaryEl, sb) {
  const q = (sb.search || '').trim().toLowerCase();
  let visible = 0;
  for (const row of listEl.querySelectorAll('.recipe-row')) {
    const name = row.dataset.name;
    const descText = (row.querySelector('.recipe-desc')?.textContent || '').toLowerCase();
    const match = !q || name.toLowerCase().includes(q) || descText.includes(q);
    row.classList.toggle('hidden', !match);
    if (match) visible++;
  }
  // Hide categories with no visible rows.
  for (const cat of listEl.querySelectorAll('.category')) {
    const anyVisible = cat.querySelectorAll('.recipe-row:not(.hidden)').length > 0;
    cat.style.display = anyVisible ? '' : 'none';
  }
  if (summaryEl) {
    const total = listEl.querySelectorAll('.recipe-row').length;
    summaryEl.textContent = q ? `${visible} / ${total}` : `${total} recipes`;
  }
}

function renderOutput() {
  const lines = [];
  const cliLines = [];
  const seenNames = new Set();
  let warning = '';
  const sandboxCount = state.sandboxes.length;

  for (const sb of state.sandboxes) {
    const name = (sb.name || '').trim();
    if (!name) {
      warning = 'A sandbox is missing a name.';
      continue;
    }
    if (!/^[A-Za-z0-9_-]+$/.test(name)) {
      warning = `Sandbox name "${name}" contains illegal characters (use letters, digits, "-" or "_").`;
    }
    if (seenNames.has(name)) {
      warning = `Sandbox name "${name}" is duplicated.`;
    }
    seenNames.add(name);

    // ---- canister.toml block ----
    lines.push(`[sandbox.${name}]`);
    const picks = [...sb.picks].sort();
    lines.push(`recipes = [${picks.map(p => `"${p}"`).join(', ')}]`);
    lines.push(`command = "${escapeToml(sb.command || '')}"`);
    if (sb.egress) {
      lines.push('');
      lines.push(`[sandbox.${name}.network]`);
      lines.push(`egress = "${sb.egress}"`);
    }
    lines.push('');

    // ---- equivalent can-run line ----
    if (sandboxCount > 1) cliLines.push(`# ${name}`);
    const flagParts = [];
    for (const p of picks) flagParts.push(`-r ${p}`);
    const cmd = (sb.command || 'bash').trim() || 'bash';
    // Note egress as a comment — there is no --egress CLI flag; the
    // override only applies via the manifest. generic-strict gives
    // egress=none directly.
    if (sb.egress) {
      const hint =
        sb.egress === 'none'
          ? "# egress=none isn't a CLI flag — compose with `-r generic-strict` for the same effect"
          : `# egress="${sb.egress}" only applies via the manifest; service recipes already enforce per-host gates`;
      cliLines.push(hint);
    }
    const cliCmd = ['can run', ...flagParts, '--', cmd].filter(Boolean).join(' ');
    cliLines.push(cliCmd);
    if (sandboxCount > 1) cliLines.push('');
  }

  if (warning) {
    showStatus(warning);
  } else {
    els.status.hidden = true;
  }

  els.output.textContent = lines.join('\n').trimEnd() + '\n';
  if (els.outputCli) {
    els.outputCli.textContent = cliLines.join('\n').trimEnd() + '\n';
  }
}

function escapeToml(s) {
  return String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

els.addSandbox.addEventListener('click', () => {
  addSandbox({ name: `sandbox-${state.nextId}`, command: 'bash', egress: '', picks: new Set() });
  render();
});

function wireCopy(buttonEl, sourceEl) {
  if (!buttonEl || !sourceEl) return;
  buttonEl.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(sourceEl.textContent);
      const orig = buttonEl.textContent;
      buttonEl.textContent = 'Copied!';
      setTimeout(() => { buttonEl.textContent = orig; }, 1500);
    } catch (err) {
      showStatus(`Clipboard copy failed: ${err.message}. Select and copy manually.`);
    }
  });
}
wireCopy(els.copy, els.output);
wireCopy(els.copyCli, els.outputCli);

init();
